function property_by_index(idx, propertynum)
{
    idx=C.int(idx);
    if (!(idx >= 0 && idx < C.propertynames.length))
        idx = C.propertynames.length - 1;

    if (propertynum)
        propertynum.value = C.propertynames[idx].prop_num;
    return C.propertynames[idx].prop_name;
}

/* He is being petrified - dialogue by inmet!tower */
const stoned_texts = [
    "You are slowing down.",            /* 5 */
    "Your limbs are stiffening.",       /* 4 */
    "Your limbs have turned to stone.", /* 3 */
    "You have turned to stone.",        /* 2 */
    "You are a statue."                 /* 1 */
];

function stoned_dialogue()
{
    let i = (C.long(C.long(C.Stoned) & C.TIMEOUT));

    if (i > 0n && i <= C.stoned_texts.length) {
        const buf = C.stackAlloc(C.BUFSZ);

        C.Strcpy(buf, C.stoned_texts[C.long(C.stoned_texts.length) - i]);
        if (C.nolimbs(C.gy.youmonst.data) && C.strstri(buf, "limbs"))
            C.strsubst(buf, "limbs", "extremities");
        C.urgent_pline("%s", buf);
    }
    switch (C.int(i)) {
    case 5: /* slowing down */
        C.HFast = 0n;
        if (C.gm.multi > 0)
            C.nomul(0);
        break;
    case 4: /* limbs stiffening */
        /* just one move left to save oneself so quit fiddling around;
           don't stop attempt to eat tin--might be lizard or acidic */
        if (!C.Popeye(C.STONED))
            C.stop_occupation();
        if (C.gm.multi > 0)
            C.nomul(0);
        break;
    case 3: /* limbs turned to stone */
        C.stop_occupation();
        C.nomul(-3); /* can't move anymore */
        C.gm.multi_reason = "getting stoned";
        C.gn.nomovemsg = C.You_can_move_again; /* not unconscious */
        /* "your limbs have turned to stone" so terminate wounded legs */
        if (C.Wounded_legs && !C.u.usteed)
            C.heal_legs(2);
        break;
    case 2: /* turned to stone */
        if ((C.long(C.HDeaf) & C.TIMEOUT) > 0n && (C.long(C.HDeaf) & C.TIMEOUT) < 5n)
            C.set_itimeout(C.propertyRef("HDeaf"), 5n); /* avoid Hear_again at tail end */
        /* if also vomiting or turning into slime, stop those (no messages) */
        if (C.Vomiting)
            C.make_vomiting(0n, 0);
        if (C.Slimed)
            C.make_slimed(0n, 0);
        break;
    default:
        break;
    }
    C.exercise(C.A_DEX, 0);
}

/* hero is getting sicker and sicker prior to vomiting */
const vomiting_texts = [
    "are feeling mildly nauseated.", /* 14 */
    "feel slightly confused.",       /* 11 */
    "can't seem to think straight.", /* 8 */
    "feel incredibly sick.",         /* 5 */
    "are about to vomit."            /* 2 */
];

function vomiting_dialogue()
{
    let txt = 0;
    const buf = C.stackAlloc(C.BUFSZ);
    let v = (C.long(C.long(C.Vomiting) & C.TIMEOUT));

    /* note: nhtimeout() hasn't decremented timed properties for the
       current turn yet, so we use Vomiting-1 here */
    switch (C.int((v - 1n))) {
    case 14:
        txt = C.vomiting_texts[0];
        break;
    case 11:
        txt = C.vomiting_texts[1];
        if (C.strstri(txt, " confused") && C.Confusion)
            txt = C.strsubst(C.strcpy(buf, txt), " confused", " more confused");
        break;
    case 6:
        C.make_stunned((C.long(C.HStun) & C.TIMEOUT) + C.long((C.rngCaller(215, "vomiting_dialogue"), C.d(2, 4, 215, "vomiting_dialogue", 1))), 0);
        if (!C.Popeye(C.VOMITING))
            C.stop_occupation();
        
    /*FALLTHRU*/
    case 9:
        C.make_confused((C.long(C.HConfusion) & C.TIMEOUT) + C.long((C.rngCaller(221, "vomiting_dialogue"), C.d(2, 4, 221, "vomiting_dialogue", 1))), 0);
        if (C.gm.multi > 0)
            C.nomul(0);
        break;
    case 8:
        txt = C.vomiting_texts[2];
        if (C.strstri(txt, " think") && C.Stunned)
            txt = C.strsubst(C.strcpy(buf, txt), "can't seem to ", "can't ");
        break;
    case 5:
        txt = C.vomiting_texts[3];
        break;
    case 2:
        txt = C.vomiting_texts[4];
        if (C.cantvomit(C.gy.youmonst.data))
            txt = "gag uncontrollably.";
        else if (C.Hallucination)
            /* "hurl" is short for "hurl chunks" which is slang for
               relatively violent vomiting... */
            txt = "are about to hurl!";
        break;
    case 0:
        C.stop_occupation();
        if (!C.cantvomit(C.gy.youmonst.data)) {
            C.morehungry(20);
            /* case 2 used to be "You suddenly vomit!" but it wasn't sudden
               since you've just been through the earlier messages of the
               countdown, and it was still possible to move around between
               that message and "You can move again." (from vomit()'s
               nomul(-2)) with no intervening message; give one here to
               have more specific point at which hero became unable to move
               [vomit() issues its own message for the cantvomit() case
               and for the FAINTING-or-worse case where stomach is empty] */
            if (C.u.uhs < C.FAINTING)
                C.You("%s!", !C.Hallucination ? "vomit" : "hurl chunks");
        }
        C.vomit();
        break;
    default:
        break;
    }
    if (txt)
        C.You1(txt);
    C.exercise(C.A_CON, 0);
}

