const levi_texts = [
    "You float slightly lower.",
    "You wobble unsteadily %s the %s."
];

function levitation_dialogue()
{
    /* -1 because the last message comes via float_down() */
    let i = (C.long(((C.long(C.HLevitation) & C.TIMEOUT) - 1n) / 2n));

    if (C.ELevitation)
        return;

    if (!C.ACCESSIBLE(C.levl[C.u.ux][C.u.uy].typ)
        && !C.is_pool_or_lava(C.u.ux,C.u.uy))
        return;

    if (((C.long(C.HLevitation) & C.TIMEOUT) % 2n) && i > 0n && i <= C.levi_texts.length) {
        let s = C.levi_texts[C.long(C.levi_texts.length) - i];

        if (C.strchr(s, 37)) {
            let danger = (Number(Boolean(C.is_pool_or_lava(C.u.ux, C.u.uy)
                              && !C.Is_waterlevel(C.u.uz))));

            C.urgent_pline(s, danger ? "over" : "in",
                         danger ? C.surface(C.u.ux, C.u.uy) : "air");
        } else
            C.pline1(s);
        C.stop_occupation();
    }
}

const slime_texts = [
    "You are turning a little %s.",   /* 5 */
    "Your limbs are getting oozy.",   /* 4 */
    "Your skin begins to peel away.", /* 3 */
    "You are turning into %s.",       /* 2 */
    "You have become %s."             /* 1 */
];

function slime_dialogue()
{
    let t = (C.long(C.long(C.Slimed) & C.TIMEOUT)), i = C.long(t / 2n);

    if (t == 1n) {
        /* display as green slime during "You have become green slime."
           but don't worry about not being able to see self; if already
           mimicking something else at the time, implicitly be revealed */
        C.gy.youmonst.m_ap_type = C.M_AP_MONSTER;
        C.gy.youmonst.mappearance = C.PM_GREEN_SLIME;
        /* no message given when 't' is odd, so no automatic update of
           self; force one */
        C.newsym(C.u.ux, C.u.uy);
    }

    if ((t % 2n) != 0n && i >= 0n && i < C.slime_texts.length) {
        const buf = C.stackAlloc(C.BUFSZ);

        C.Strcpy(buf, C.slime_texts[C.long(C.slime_texts.length) - i - 1n]);
        if (C.nolimbs(C.gy.youmonst.data) && C.strstri(buf, "limbs"))
            C.strsubst(buf, "limbs", "extremities");

        if (C.strchr(buf, 37)) {
            if (i == 4n) {  /* "you are turning green" */
                if (!C.Blind) /* [what if you're already green?] */
                    C.urgent_pline(buf, C.hcolor(C.NH_GREEN));
            } else {
                C.urgent_pline(buf, C.an(C.Hallucination ? C.rndmonnam(0)
                                                   : "green slime"));
            }
        } else {
            C.urgent_pline("%s", buf);
        }
    }

    switch (i) {
    case 3n:  /* limbs becoming oozy */
        C.HFast = 0n; /* lose intrinsic speed */
        if (!C.Popeye(C.SLIMED))
            C.stop_occupation();
        if (C.gm.multi > 0)
            C.nomul(0);
        break;
    case 2n: /* skin begins to peel */
        if ((C.long(C.HDeaf) & C.TIMEOUT) > 0n && (C.long(C.HDeaf) & C.TIMEOUT) < 5n)
            C.set_itimeout(C.propertyRef("HDeaf"), 5n); /* avoid Hear_again at tail end */
        break;
    case 1n: /* turning into slime */
        /* if also turning to stone, stop doing that (no message) */
        if (C.Stoned)
            C.make_stoned(0n, 0, C.KILLED_BY_AN, 0);
        break;
    }
    C.exercise(C.A_DEX, 0);
}



function burn_away_slime()
