/* countdown timer for turning into green slime has run out; kill our hero */
function slimed_to_death(kptr)
{
    let save_mvflags;

    /* redundant: polymon() cures sliming when polying into green slime */
    if (C.Upolyd && C.samePtr(C.gy.youmonst.data, C.mons[C.PM_GREEN_SLIME])) {
        C.dealloc_killer(kptr);
        return;
    }
    /* more sure killer reason is set up */
    if (kptr && C.loadChar(kptr.name)) {
        C.svk.killer.format = kptr.format;
        C.Strcpy(C.svk.killer.name, kptr.name);
    } else {
        C.svk.killer.format = C.NO_KILLER_PREFIX;
        C.Strcpy(C.svk.killer.name, "turned into green slime");
    }
    C.dealloc_killer(kptr);

    /*
     * Polymorph into a green slime, which might destroy some worn armor
     * (potentially affecting bones) and dismount from steed.
     * Can't be Unchanging; wouldn't have turned into slime if we were.
     * Despite lack of Unchanging, neither done() nor savelife() calls
     * rehumanize() if hero dies while polymorphed.
     * polymon() undoes the slime countdown's mimick-green-slime hack
     * but does not perform polyself()'s light source bookkeeping.
     * No longer need to manually increment uconduct.polyselfs to reflect
     * [formerly implicit] change of form; polymon() takes care of that.
     * Temporarily ungenocide if necessary.
     */
    if (C.emits_light(C.gy.youmonst.data))
        C.del_light_source(C.LS_MONSTER, C.monst_to_any(C.gy.youmonst));
    save_mvflags = C.svm.mvitals[C.PM_GREEN_SLIME].mvflags;
    C.svm.mvitals[C.PM_GREEN_SLIME].mvflags = save_mvflags & ~C.G_GENOD;
    /* become a green slime; also resets youmonst.m_ap_type+.mappearance */
    C.polymon(C.PM_GREEN_SLIME);
    C.svm.mvitals[C.PM_GREEN_SLIME].mvflags = save_mvflags;
    done_timeout(C.TURNED_SLIME, C.SLIMED);

    /* life-saved; even so, hero still has turned into green slime;
       player may have genocided green slimes after being infected */
    if ((C.svm.mvitals[C.PM_GREEN_SLIME].mvflags & C.G_GENOD) != 0) {
        const slimebuf = C.stackAlloc(C.BUFSZ);

        C.svk.killer.format = C.KILLED_BY;
        C.Strcpy(C.svk.killer.name, "slimicide");
        /* vary the message depending upon whether life-save was due to
           amulet or due to declining to die in explore or wizard mode */
        C.Strcpy(slimebuf, "green slime has been genocided...");
        if (C.iflags.last_msg == C.PLNMSG_OK_DONT_DIE)
            /* follows "OK, so you don't die." and arg is second sentence */
            C.urgent_pline("Yes, you do.  %s", C.upstart(slimebuf));
        else
            /* follows "The medallion crumbles to dust." */
            C.urgent_pline("Unfortunately, %s", slimebuf);
        /* die again; no possibility of amulet this time */
        C.done(C.GENOCIDED); /* [should it be done_timeout(GENOCIDED, SLIMED)?] */
        /* could be life-saved again (only in explore or wizard mode)
           but green slimes are gone; just stay in current form */
    }
    return;
}

/* Intrinsic Passes_walls is temporary when your god is trying to fix
   all troubles and then TROUBLE_STUCK_IN_WALL calls safe_teleds() but
   it can't find anywhere to place you.  If that happens you get a small
   value for (HPasses_walls & TIMEOUT) to move somewhere yourself.
   Message given is "you feel much slimmer" as a joke hint that you can
   move between things which are closely packed--like the substance of
   solid rock! */
const phaze_texts = [
    "You start to feel bloated.",
    "You are feeling rather flabby.",
];

function phaze_dialogue()
{
    let i = (C.long((C.long(C.HPasses_walls) & C.TIMEOUT) / 2n));

    if (C.EPasses_walls || (C.long(C.HPasses_walls) & ~C.TIMEOUT))
        return;

    if (((C.long(C.HPasses_walls) & C.TIMEOUT) % 2n) && i > 0n && i <= C.phaze_texts.length)
        C.pline("%s", C.phaze_texts[C.long(C.phaze_texts.length) - i]);
}

/* Similar to Passes_walls, if prayer tries to save hero from a poison
   gas region but can't, (HMagical_breathing & TIMEOUT) will be set to
   a small value.  Unlike Passes_walls, there's no joke message. */
const region_texts = [
    "You seem to have some trouble breathing.",
    "The air here seems foul.",
];

function region_dialogue()
{
    let no_need_to_breathe, in_poison_gas_cloud;
    let r = (C.long(C.long(C.HMagical_breathing) & C.TIMEOUT)), i = C.long(r / 2n);

    /* might have poly'd into non-breather or moved out of gas cloud */
    C.HMagical_breathing &= ~C.TIMEOUT;
    no_need_to_breathe = C.Breathless;
    in_poison_gas_cloud = C.region_danger();
    C.HMagical_breathing |= r;
    if (no_need_to_breathe || !in_poison_gas_cloud)
        return;

    if ((r % 2n) && i > 0n && i <= C.region_texts.length)
        C.pline("%s", C.region_texts[C.long(C.region_texts.length) - i]);
}

/* when a status timeout is fatal, keep the status line indicator shown
   during end of game rundown (and potential dumplog);
   timeout has already counted down to 0 by the time we get here */
function done_timeout(how, which)
{
    how=C.int(how);which=C.int(which);
    const intrinsic_p = C.propRef(which);

    intrinsic_p.value |= C.I_SPECIAL; /* affects final disclosure */
    C.done(how);

    /* life-saved */
    intrinsic_p.value &= ~C.I_SPECIAL;
    C.disp.botl = 1;
}

function nh_timeout()
{
    let upp;
    let kptr;
    let was_flying;
    let sleeptime;
    let m_idx;
    let baseluck = (C.flags.moonphase == C.FULL_MOON) ? 1 : 0;

    if (C.flags.friday13)
        baseluck -= 1;

    if (C.svq.quest_status.killed_leader)
        baseluck -= 4;

    if (C.Role_if(C.PM_ARCHEOLOGIST) && C.uarmh && C.uarmh.otyp == C.FEDORA)
        baseluck += 1;

    if (C.u.uluck != baseluck
        && C.svm.moves % (C.long((C.u.uhave.amulet || C.u.ugangr) ? 300 : 600)) == 0) {
        /* Cursed luckstones stop bad luck from timing out; blessed luckstones
         * stop good luck from timing out; normal luckstones stop both;
         * neither is stopped if you don't have a luckstone.
         * Luck is based at 0 usually, +1 if a full moon and -1 on Friday 13th
         */
        let time_luck = C.stone_luck(0);
        let nostone = Number(Boolean(!C.carrying(C.LUCKSTONE) && !C.stone_luck(1)));

        if (C.u.uluck > baseluck && (nostone || time_luck < 0))
            C.u.uluck--;
        else if (C.u.uluck < baseluck && (nostone || time_luck > 0))
            C.u.uluck++;
    }
    if (C.u.uinvulnerable)
        return; /* things past this point could kill you */
    if (C.Stoned)
        stoned_dialogue();
    if (C.Slimed)
        slime_dialogue();
    if (C.Vomiting)
        vomiting_dialogue();
    if (C.Strangled)
        choke_dialogue();
    if (C.Sick)
        sickness_dialogue();
    if (C.long(C.HLevitation) & C.TIMEOUT)
        levitation_dialogue();
    if (C.long(C.HPasses_walls) & C.TIMEOUT)
        phaze_dialogue();
    if (C.long(C.HMagical_breathing) & C.TIMEOUT)
        region_dialogue();
    if (C.long(C.HSleepy) & C.TIMEOUT)
        sleep_dialogue();
    if (C.u.mtimedone && !--C.u.mtimedone) {
        if (C.Unchanging)
            C.u.mtimedone = (C.rngCaller(643, "nh_timeout"), C.rnd(100 * C.gy.youmonst.data.mlevel + 1, 643, "nh_timeout", 1));
        else if (C.is_were(C.gy.youmonst.data))
            C.you_unwere(0); /* if polycontrl, asks whether to rehumanize */
        else
            C.rehumanize();
    }
    if (C.u.ucreamed)
        C.u.ucreamed--;

    /* Dissipate spell-based protection. */
    if (C.u.usptime) {
        if (--C.u.usptime == 0 && C.u.uspellprot) {
            C.u.usptime = C.u.uspmtime;
            C.u.uspellprot--;
            C.find_ac();
            if (!C.Blind)
                C.Norep("The %s haze around you %s.", C.hcolor(C.NH_GOLDEN),
                      C.u.uspellprot ? "becomes less dense" : "disappears");
        }
    }

    if (C.u.ugallop) {
        if (--C.u.ugallop == 0n && C.u.usteed)
            C.pline("%s stops galloping.", C.Monnam(C.u.usteed));
    }

    was_flying = C.Flying;
    for (let propertyIndex = 0; propertyIndex < C.PROP_COUNT; propertyIndex++) {
        upp = C.u.uprops[propertyIndex];
        if ((upp.intrinsic & C.TIMEOUT) && !(C.long(--upp.intrinsic) & C.TIMEOUT)) {
            kptr = C.find_delayed_killer(propertyIndex);
            switch (propertyIndex) {
            case C.STONED:
                if (kptr && C.loadChar(kptr.name)) {
                    C.svk.killer.format = kptr.format;
                    C.Strcpy(C.svk.killer.name, kptr.name);
                } else {
                    C.svk.killer.format = C.NO_KILLER_PREFIX;
                    C.Strcpy(C.svk.killer.name, "killed by petrification");
                }
                C.dealloc_killer(kptr);
                /* (unlike sliming, you aren't changing form here) */
                done_timeout(C.STONING, C.STONED);
                break;
            case C.SLIMED:
                slimed_to_death(kptr); /* done_timeout(TURNED_SLIME,SLIMED) */
                break;
            case C.VOMITING:
                C.make_vomiting(0n, 1);
                break;
            case C.SICK:
                /* hero might be able to bounce back from food poisoning,
                   but not other forms of illness */
                if ((C.u.usick_type & C.SICK_NONVOMITABLE) == 0
                    && (C.rngCaller(696, "nh_timeout"), C.rn2(100, 696, "nh_timeout", 1)) < C.ACURR(C.A_CON)) {
                    C.You("have recovered from your illness.");
                    C.make_sick(0, 0, 0, C.SICK_ALL);
                    C.exercise(C.A_CON, 0);
                    C.adjattrib(C.A_CON, -1, 1);
                    break;
                }
                C.urgent_pline("You die from your illness.");
                if (kptr && C.loadChar(kptr.name)) {
                    C.svk.killer.format = kptr.format;
                    C.Strcpy(C.svk.killer.name, kptr.name);
                } else {
                    C.svk.killer.format = C.KILLED_BY_AN;
                    C.storeChar(C.svk.killer.name, 0); /* take the default */
                }
                C.dealloc_killer(kptr);

                if ((m_idx = C.name_to_mon(C.svk.killer.name,
                                         0)) >= C.LOW_PM) {
                    if (C.type_is_pname(C.mons[m_idx])) {
                        C.svk.killer.format = C.KILLED_BY;
                    } else if (C.mons[m_idx].geno & C.G_UNIQ) {
                        C.Strcpy(C.svk.killer.name, C.the(C.svk.killer.name));
                        C.svk.killer.format = C.KILLED_BY;
                    }
                }
                done_timeout(C.POISONING, C.SICK);
                C.u.usick_type = 0;
                break;
            case C.FAST:
                if (!C.Very_fast)
                    C.You_feel("yourself slow down%s.",
                             C.Fast ? " a bit" : "");
                break;
            case C.CONFUSION:
                /* So make_confused works properly */
                C.set_itimeout(C.propertyRef("HConfusion"), 1n);
                C.make_confused(0n, 1);
                if (!C.Confusion)
                    C.stop_occupation();
                break;
            case C.STUNNED:
                C.set_itimeout(C.propertyRef("HStun"), 1n);
                C.make_stunned(0n, 1);
                if (!C.Stunned)
                    C.stop_occupation();
                break;
            case C.BLINDED: {
                let was_blind = !!C.Blind;

                C.set_itimeout(C.propertyRef("HBlinded"), 1n);
                C.make_blinded(0n, 1);
                if (was_blind && !C.Blind)
                    C.stop_occupation();
                break;
            }
            case C.DEAF:
                C.set_itimeout(C.propertyRef("HDeaf"), 1n);
                C.make_deaf(0n, 1);
                C.disp.botl = 1;
                if (!C.Deaf)
                    C.stop_occupation();
                break;
            case C.INVIS:
                C.newsym(C.u.ux, C.u.uy);
                if (!C.Invis && !C.BInvis && !C.Blind) {
                    C.You(!C.See_invisible
                            ? "are no longer invisible."
                            : "can no longer see through yourself.");
                    C.stop_occupation();
                }
                break;
            case C.SEE_INVIS:
                C.set_mimic_blocking(); /* do special mimic handling */
                C.see_monsters();       /* make invis mons appear */
                C.newsym(C.u.ux, C.u.uy);   /* make self appear */
                C.stop_occupation();
                break;
            case C.WOUNDED_LEGS:
                C.heal_legs(0);
                C.stop_occupation();
                break;
            case C.HALLUC:
                C.set_itimeout(C.propertyRef("HHallucination"), 1n);
                C.make_hallucinated(0n, 1, 0n);
                if (!C.Hallucination)
                    C.stop_occupation();
                break;
            case C.SLEEPY:
                if (C.unconscious() || C.Sleep_resistance) {
                    C.incr_itimeout(C.propertyRef("HSleepy"), (C.rngCaller(786, "nh_timeout"), C.rnd(100, 786, "nh_timeout", 1)));
                } else if (C.Sleepy) {
                    C.You("fall asleep.");
                    sleeptime = (C.rngCaller(789, "nh_timeout"), C.rnd(20, 789, "nh_timeout", 1));
                    fall_asleep(-sleeptime, 1);
                    C.incr_itimeout(C.propertyRef("HSleepy"), sleeptime + (C.rngCaller(791, "nh_timeout"), C.rnd(100, 791, "nh_timeout", 1)));
                }
                break;
            case C.LEVITATION:
                /* timed Levitation is ordinary, timed Flying is via
                   #wizintrinsic only; still, we want to avoid float_down()
                   reporting "you have stopped levitating and are now flying"
                   when both are timing out together; if that is about to
                   happen, end Flying early to skip feedback about it;
                   assumes Levitation is handled before Flying */
                if ((C.long(C.HFlying) & C.TIMEOUT) == 1n)
                    C.set_itimeout(C.propertyRef("HFlying"), 0n); /* bypass 'case FLYING' */
                C.float_down(C.I_SPECIAL | C.TIMEOUT, 0n);
                break;
            case C.FLYING:
                /* timed Flying is via #wizintrinsic only */
                if (was_flying && !C.Flying) {
                    C.disp.botl = 1;
                    C.You("land.");
                    C.spoteffects(1);
                }
                break;
            case C.ACID_RES:
                if (!C.Acid_resistance) {
                    if (C.eating_dangerous_corpse(C.ACID_RES)) {
                        /* extend temporary acid resistance if in midst
                           of eating an acidic corpse; this will repeat
                           until eating is finished or interrupted */
                        C.set_itimeout(C.propRef(C.ACID_RES), 1n);
                        break;
                    }
                    if (!C.Unaware)
                        C.You("no longer feel safe from acid.");
                }
                break;
            case C.STONE_RES:
                if (!C.Stone_resistance) {
                    if (C.eating_dangerous_corpse(C.STONE_RES)) {
                        /* extend temporary stoning resistance if in midst
                           of eating a stoning corpse; this will repeat
                           until eating is finished or interrupted */
                        C.set_itimeout(C.propRef(C.STONE_RES), 1n);
                        break;
                    }
                    if (!C.Unaware)
                        C.You("no longer feel secure from petrification.");
                    /* no-op if not wielding a cockatrice corpse;
                       uswapwep case is always a no-op because two-weapon
                       combat is only possible with two one-handed weapons
                       or weapon tools, not corpses */
                    C.wielding_corpse(C.uwep, 0, 0);
                    C.wielding_corpse(C.uswapwep, 0, 0);
                }
                break;
            case C.FIRE_RES:
                /* timed fire resistance and timed water walking combine
                   as a way to survive lava after multiple life-saving
                   attempts fail to relocate hero; skip timeout message
                   if hero has acquired fire resistance in the meantime */
                if (!C.Fire_resistance)
                    C.Your("temporary ability to survive burning has ended.");
                break;
            case C.WWALKING:
                /* [see fire resistance] */
                if (!C.Wwalking)
                    C.Your("temporary ability to walk on liquid has ended.");
                break;
            case C.DISPLACED:
                if (!C.Displaced) /* give a message */
                    C.toggle_displacement(0, 0n, 0);
                break;
            case C.WARN_OF_MON:
                /* timed Warn_of_mon is via #wizintrinsic only */
                if (!C.Warn_of_mon) {
                    let wptr = C.svc.context.warntype.species;

                    C.svc.context.warntype.species = 0;
                    C.svc.context.warntype.speciesidx = C.NON_PM;
                    if (wptr)
                        C.You("are no longer warned about %s.",
                            C.makeplural(wptr.pmnames[C.NEUTRAL]));
                }
                break;
            case C.PASSES_WALLS:
                if (!C.Passes_walls) {
                    if (C.stuck_in_wall())
                        C.You_feel("hemmed in again.");
                    else
                        C.pline("You're back to your %s self again.",
                              !C.Upolyd ? "normal" : "unusual");
                }
                break;
            case C.MAGICAL_BREATHING:
                if (!C.Breathless) {
                    if (C.region_danger())
                        C.You("cough%s",
                            C.Poison_resistance ? "." : " and spit blood!");
                }
                break;
            case C.STRANGLED:
                C.svk.killer.format = C.KILLED_BY;
                C.Strcpy(C.svk.killer.name,
                       (C.u.uburied) ? "suffocation" : "strangulation");
                done_timeout(C.DIED, C.STRANGLED);
                /* must be declining to die in explore|wizard mode;
                   treat like being cured of strangulation by prayer */
                if (C.uamul && C.uamul.otyp == C.AMULET_OF_STRANGULATION) {
                    C.Your("amulet vanishes!");
                    C.useup(C.uamul);
                }
                break;
            case C.FUMBLING:
                /* call this only when a move took place.  */
                /* otherwise handle fumbling msgs locally. */
                if (C.u.umoved && !(C.Levitation || C.Flying)) {
                    slip_or_trip();
                    C.nomul(-2);
                    C.gm.multi_reason = "fumbling";
                    C.gn.nomovemsg = "";
                    /* The more you are carrying the more likely you
                     * are to make noise when you fumble.  Adjustments
                     * to this number must be thoroughly play tested.
                     */
                    if ((C.inv_weight() > (C.WT_NOISY_INV * -1))) {
                        if (!C.Deaf)
                            C.You("make a lot of noise!");
                        C.wake_nearby(0);
                    }
                }
                /* from outside means slippery ice; don't reset
                   counter if that's the only fumble reason */
                C.HFumbling &= ~C.FROMOUTSIDE;
                if (C.Fumbling)
                    C.incr_itimeout(C.propertyRef("HFumbling"), (C.rngCaller(924, "nh_timeout"), C.rnd(20, 924, "nh_timeout", 1)));

                if (C.iflags.defer_decor) {
                    /* 'mention_decor' was deferred for message sequencing
                       reasons; catch up now */
                    C.deferred_decor(0);
                }
                break;
            case C.DETECT_MONSTERS:
                C.see_monsters();
                break;
            case C.GLIB:
                C.make_glib(0); /* might update persistent inventory */
                break;
            case C.PROT_FROM_SHAPE_CHANGERS:
                /* timed Protection_from_shape_changers is via
                   #wizintrinsic only */
                if (!C.Protection_from_shape_changers)
                    C.restartcham();
                break;
            }
        }
    }

    run_timers();
}

function fall_asleep(how_long, wakeup_msg)
{
    how_long=C.int(how_long);wakeup_msg=C.boolean(wakeup_msg);
    C.stop_occupation();
    C.nomul(how_long);
    C.gm.multi_reason = "sleeping";
// #if 0   
/* this was broken; the fix for 'how_long' will result in changed
         * behavior for sounds that don't go through You_hear() so needs
         * testing */
//     
/* You_hear() produces "You dream that you hear ..." when sleeping;
       other sound messages will either honor or ignore Deaf */
//     if (wakeup_msg && gm.multi == how_long) {
//         
/* caller can follow with a direct call to Hear_again() if
           there's a need to override this when wakeup_msg is true */
//         
/* 5.0: how_long is negative so wasn't actually incrementing the
           deafness timeout when it used to be passed as-is */
//         incr_itimeout(&HDeaf, abs(how_long));
//         disp.botl = TRUE;
//         ga.afternmv = Hear_again; 
/* this won't give any messages */
//     }
// #endif
    /* early wakeup from combat won't be possible until next monster turn */
    C.u.usleep = C.svm.moves;
    C.gn.nomovemsg = wakeup_msg ? "You wake up." : C.You_can_move_again;
}

/* Attach an egg hatch timeout to the given egg.
 *      when = Time to hatch, usually only passed if re-creating an
 *             existing hatch timer. Pass 0L for random hatch time.
 */
function attach_egg_hatch_timeout(egg, when)
{
    when=C.long(when);
    let i;

    /* stop previous timer, if any */
    stop_timer(C.HATCH_EGG, C.obj_to_any(egg));

    /*
     * Decide if and when to hatch the egg.  The old hatch_it() code tried
     * once a turn from age 151 to 200 (inclusive), hatching if it rolled
     * a number x, 1<=x<=age, where x>150.  This yields a chance of
     * hatching > 99.9993%.  Mimic that here.
     */
    if (!when) {
        for (i = (C.MAX_EGG_HATCH_TIME - 50) + 1; i <= C.MAX_EGG_HATCH_TIME; i++)
            if ((C.rngCaller(996, "attach_egg_hatch_timeout"), C.rnd(i, 996, "attach_egg_hatch_timeout", 1)) > 150) {
                /* egg will hatch */
                when = C.long(C.long(i));
                break;
            }
    }
    if (when) {
        start_timer(when, C.TIMER_OBJECT, C.HATCH_EGG, C.obj_to_any(egg));
    }
}

/* prevent an egg from ever hatching */
function kill_egg(egg)
{
    /* stop previous timer, if any */
    stop_timer(C.HATCH_EGG, C.obj_to_any(egg));
}

/* timer callback routine: hatch the given egg */
function hatch_egg(arg, timeout)
{
    timeout=C.long(timeout);
    let egg;
    let mon, mon2;
    const cc = C.coordLocal();
    const x = C.coordxyLocal(), y = C.coordxyLocal();
    let yours, silent, knows_egg = 0;
    let cansee_hatchspot = 0;
    let i, mnum, hatchcount = 0;

    egg = arg.a_obj;
    /* sterilized while waiting */
    if (egg.corpsenm == C.NON_PM)
        return;

    mon = mon2 = 0;
    mnum = C.big_to_little(egg.corpsenm);
    /* The identity of one's father is learned, not innate */
    yours = (Number(Boolean(egg.spe || (!C.flags.female && C.carried(egg) && !(C.rngCaller(1035, "hatch_egg"), C.rn2(2, 1035, "hatch_egg", 1))))));
    silent = (timeout != C.svm.moves); /* hatched while away */

    /* only can hatch when in INVENT, FLOOR, MINVENT;
       get_obj_location() will fail for MIGRATING, also for CONTAINED
       and BURIED when the flags for those aren't included in the call */
    if (C.get_obj_location(egg, x, y, 0)) {
        hatchcount = (C.rngCaller(1042, "hatch_egg"), C.rnd(C.int(egg.quan), 1042, "hatch_egg", 1));
        cansee_hatchspot = Number(Boolean(C.cansee(x.value, y.value) && !silent));
        if (!(C.mons[mnum].geno & C.G_UNIQ)
            && !(C.svm.mvitals[mnum].mvflags & (C.G_GENOD | C.G_EXTINCT))) {
            for (i = hatchcount; i > 0; i--) {
                if (!C.enexto(cc, x.value, y.value, C.mons[mnum])
                    || !(mon = C.makemon(C.mons[mnum], cc.x, cc.y,
                                       C.NO_MINVENT | C.MM_NOMSG)))
                    break;
                /* tame if your own egg hatches while you're on the
                   same dungeon level, or any dragon egg which hatches
                   while it's in your inventory */
                if ((yours && !silent)
                    || (C.carried(egg) && mon.data.mlet == C.S_DRAGON)) {
                    if (C.tamedog(mon, 0, 0)) {
                        if (C.carried(egg) && mon.data.mlet != C.S_DRAGON)
                            mon.mtame = 20;
                    }
                }
                if (C.svm.mvitals[mnum].mvflags & C.G_EXTINCT)
                    break;  /* just made last one */
                mon2 = mon; /* in case makemon() fails on 2nd egg */
            }
            if (!mon)
                mon = mon2;
            hatchcount -= i;
            egg.quan -= C.long(hatchcount);
        }
// #if 0
//     
/*
     * We could possibly hatch while migrating, but the code isn't
     * set up for it...
     */
//     } else if (obj->where == OBJ_MIGRATING) {
//         
/*
         * We can do several things.  The first ones that come to
         * mind are:
         * + Create the hatched monster then place it on the migrating
         *   mons list.  This is tough because all makemon() is made
         *   to place the monster as well. Makemon() also doesn't lend
         *   itself well to splitting off a "not yet placed" subroutine.
         * + Mark the egg as hatched, then place the monster when we
         *   place the migrating objects.
         * + Or just kill any egg which gets sent to another level.
         *   Falling is the usual reason such transportation occurs.
         */
//         cansee_hatchspot = FALSE;
//         mon = ???;
// #endif
    }

    if (mon) {
        const monnambuf = C.stackAlloc(C.BUFSZ), carriedby = C.stackAlloc(C.BUFSZ);
        let siblings = (hatchcount > 1), redraw = 0;

        if (cansee_hatchspot) {
            /* [bug?  m_monnam() yields accurate monster type
               regardless of hallucination] */
            C.Sprintf(monnambuf, "%s%s", siblings ? "some " : "",
                    siblings ? C.makeplural(C.m_monnam(mon)) : C.an(C.m_monnam(mon)));
            /* we don't learn the egg type here because learning
               an egg type requires either seeing the egg hatch
               or being familiar with the egg already,
               as well as being able to see the resulting
               monster, checked below
            */
        }
        switch (egg.where) {
        case C.OBJ_INVENT:
            knows_egg = 1; /* true even if you are blind */
            if (!cansee_hatchspot)
                C.You_feel("%s %s from your pack!", C.something,
                         C.locomotion(mon.data, "drop"));
            else
                C.You_see("%s %s out of your pack!", monnambuf,
                        C.locomotion(mon.data, "drop"));
            if (yours) {
                C.pline("%s %s %s like \"%s%s\"",
                      siblings ? "Their" : "Its",
                      C.ing_suffix(C.cry_sound(mon)),
                      (C.is_silent(mon.data) || C.Deaf) ? "seems" : "sounds",
                      C.flags.female ? "mommy" : "daddy", egg.spe ? "." : "?");
            } else if (mon.data.mlet == C.S_DRAGON && !C.Deaf) {
// Inactive sound macro:                 C.SetVoice(mon, 0, 80, 0);
                C.verbalize("Gleep!"); /* Mything eggs :-) */
            }
            break;

        case C.OBJ_FLOOR:
            if (cansee_hatchspot) {
                knows_egg = 1;
                C.You_see("%s hatch.", monnambuf);
                redraw = 1; /* update egg's map location */
            }
            break;

        case C.OBJ_MINVENT:
            if (cansee_hatchspot) {
                /* egg carrying monster might be invisible */
                mon2 = egg.ocarry;
                if (C.canseemon(mon2)
                    && (!mon2.wormno || C.cansee(mon2.mx, mon2.my))) {
                    C.Sprintf(carriedby, "%s pack",
                            C.s_suffix(C.a_monnam(mon2)));
                    knows_egg = 1;
                } else if (C.is_pool(mon.mx, mon.my)) {
                    C.Strcpy(carriedby, "empty water");
                } else {
                    C.Strcpy(carriedby, "thin air");
                }
                C.You_see("%s %s out of %s!", monnambuf,
                        C.locomotion(mon.data, "drop"), carriedby);
            }
            break;
// #if 0
//         case OBJ_MIGRATING:
//             break;
// #endif
        default:
            C.impossible("egg hatched where? (%d)", C.int(egg.where));
            break;
        }

        if (cansee_hatchspot && knows_egg)
            learn_egg_type(mnum);

        if (egg.quan > 0) {
            /* still some eggs left; we didn't split the stack, just
               subtracted from quantity so weight needs to be updated;
               for remainder of stack, add a new, short hatch timer */
            attach_egg_hatch_timeout(egg, C.long((C.rngCaller(1172, "hatch_egg"), C.rnd(12, 1172, "hatch_egg", 1))));
            /* container_weight(arg) updates arg->owt, and if contained,
               its enclosing container arg->ocontainer (recursively)
               [egg won't be contained due to conditions imposed above] */
            C.container_weight(egg);
        } else if (C.carried(egg)) {
            C.useup(egg);
        } else {
            /* free egg here because we use it above */
            C.obj_extract_self(egg);
            C.obfree(egg, 0);
            if ((mon = C.m_at(x.value,y.value)) && !C.hideunder(mon) && C.cansee(x.value, y.value))
                redraw = 1;
        }
        if (redraw)
            C.newsym(x.value, y.value);
    }
}

/* Learn to recognize eggs of the given type. */
function learn_egg_type(mnum)
{
    mnum=C.int(mnum);
    /* baby monsters hatch from grown-up eggs */
    mnum = C.little_to_big(mnum);
    C.svm.mvitals[mnum].mvflags |= C.MV_KNOWS_EGG;
    /* we might have just learned about other eggs being carried */
    C.update_inventory();
}

/* Attach a fig_transform timeout to the given figurine. */
function attach_fig_transform_timeout(figurine)
{
    let i;

    /* stop previous timer, if any */
    stop_timer(C.FIG_TRANSFORM, C.obj_to_any(figurine));

    /*
     * Decide when to transform the figurine.
     */
    i = (C.rngCaller(1214, "attach_fig_transform_timeout"), C.rnd(9000, 1214, "attach_fig_transform_timeout", 1)) + 200;
    /* figurine will transform */
    start_timer(C.long(i), C.TIMER_OBJECT, C.FIG_TRANSFORM,
                       C.obj_to_any(figurine));
}

/* give a fumble message */
function slip_or_trip()
{
    let otmp = C.vobj_at(C.u.ux, C.u.uy), otmp2, saddle;
    let what;
    const buf = C.stackAlloc(C.BUFSZ);
    let on_foot = !C.u.usteed;

    if (otmp && on_foot && !C.u.uinwater && C.is_pool(C.u.ux, C.u.uy))
        otmp = 0;

    if (otmp && on_foot) { /* trip over something in particular */
        /*
          If there is only one item, it will have just been named
          during the move, so refer to it by pronoun; otherwise,
          if the top item has been or can be seen, refer to it by
          name; if not, look for rocks to trip over; trip over
          anonymous "something" if there aren't any rocks.
        */
        what = (C.iflags.last_msg == C.PLNMSG_ONE_ITEM_HERE)
                ? ((otmp.quan == 1n) ? "it"
                      : C.Hallucination ? "they" : "them")
                : (otmp.dknown || !C.Blind)
                      ? C.doname(otmp)
                      : ((otmp2 = C.sobj_at(C.ROCK, C.u.ux, C.u.uy)) == 0
                             ? C.something
                             : (otmp2.quan == 1n ? "a rock" : "some rocks"));
        if (C.Hallucination) {
            what = C.strcpy(buf, what);
            C.storeChar(buf, C.highc(C.loadChar(buf)));
            C.pline("Egads!  %s bite%s your %s!", what,
                  (!otmp || otmp.quan == 1n) ? "s" : "", C.body_part(C.FOOT));
        } else {
            C.You("trip over %s.", what);
        }
        if (!C.uarmf && otmp.otyp == C.CORPSE
            && C.touch_petrifies(C.mons[otmp.corpsenm]) && !C.Stone_resistance) {
            C.Sprintf(C.svk.killer.name, "tripping over %s corpse",
                    C.an(C.mons[otmp.corpsenm].pmnames[C.NEUTRAL]));
            C.instapetrify(C.svk.killer.name);
        }
    } else if ((C.long(C.HFumbling) & C.FROMOUTSIDE) || (C.is_ice(C.u.ux, C.u.uy) && !(C.rngCaller(1262, "slip_or_trip"), C.rn2(3, 1262, "slip_or_trip", 1)))) {
        /* is fumbling from ice alone? */
        let ice_only = !(C.EFumbling || (C.long(C.HFumbling) & ~C.FROMOUTSIDE));

        C.pline("%s %s %s the ice.",
              C.u.usteed ? C.upstart(C.x_monnam(C.u.usteed, C.ARTICLE_THE, 0,
                                          C.SUPPRESS_SADDLE, 0))
                       : "You",
              /* "steed": arbitrary value that will use third person verb
                 regardless of what u.usteed might be named, as opposed to
                 "you" (second person, which won't have final 's' added) */
              C.vtense(C.u.usteed ? "steed" : "you", (C.rngCaller(1273, "slip_or_trip"), C.rn2(2, 1273, "slip_or_trip", 1)) ? "slip" : "slide"),
              /* sometimes slipping due to ice occurs during turn that hero
                 has just moved off the ice; phrase things differently then */
              C.is_ice(C.u.ux, C.u.uy) ? "on" : "off");
        /* fumbling outside of ice while mounted always causes the hero to
           fall from the saddle (unless it is cursed), so to avoid a
           counterintuitive effect where ice makes riding _less_ hazardous,
           unconditionally dismount if fumbling is from a non-ice source */
        if (!on_foot
            && ((saddle = C.which_armor(C.u.usteed, C.W_SADDLE)) == 0
                || !saddle.cursed)
            && (!ice_only || !(C.rngCaller(1284, "slip_or_trip"), C.rn2(3, 1284, "slip_or_trip", 1)))) {
            C.You("lose your balance.");
            C.dismount_steed(C.DISMOUNT_FELL);
        } else if (!(C.rngCaller(1287, "slip_or_trip"), C.rn2(10 + C.ACURR(C.A_DEX), 1287, "slip_or_trip", 1))) {
            /* Maybe slip in a random direction.  This takes place after
               the hero has already changed location.  If the hero is
               in grid bug form, only allow forward hurtle, otherwise a
               90 degree orthogonal one after the step would make the
               combined move appear to be a single diagonal step. */
            if (!C.NODIAG(C.u.umonnum))
                C.confdir(1); /* sets u.dx and u.dy */
            /* Only hurtle if the random direction won't move hero back
               to same spot where this move started. */
            if (C.u.ux + C.u.dx != C.u.ux0 || C.u.uy + C.u.dy != C.u.uy0)
                C.hurtle(C.u.dx, C.u.dy, 1, 0);
        }
    } else {
        if (on_foot) {
            switch ((C.rngCaller(1302, "slip_or_trip"), C.rn2(4, 1302, "slip_or_trip", 1))) {
            case 1:
                C.You("trip over your own %s.",
                    C.Hallucination ? "elbow" : C.makeplural(C.body_part(C.FOOT)));
                break;
            case 2:
                C.You("slip %s.",
                    C.Hallucination ? "on a banana peel" : "and nearly fall");
                break;
            case 3:
                C.You("flounder.");
                break;
            default:
                C.You("stumble.");
                break;
            }

        /* mounted; saddle should never end up being Null here;
           don't fall off when it happens to be cursed */
        } else if ((saddle = C.which_armor(C.u.usteed, C.W_SADDLE)) == 0
                   || !saddle.cursed) {
            switch ((C.rngCaller(1323, "slip_or_trip"), C.rn2(4, 1323, "slip_or_trip", 1))) {
            case 1:
                C.Your("%s slip out of the stirrups.",
                     C.makeplural(C.body_part(C.FOOT)));
                break;
            case 2:
                C.You("let go of the reins.");
                break;
            case 3:
                C.You("bang into the saddle-horn.");
                break;
            default:
                C.You("slide to one side of the saddle.");
                break;
            }
            C.dismount_steed(C.DISMOUNT_FELL);
        }
    }
}

/* Print a lamp flicker message with tailer.  Only called if seen. */
function see_lamp_flicker(obj, tailer)
{
    switch (obj.where) {
    case C.OBJ_INVENT:
    case C.OBJ_MINVENT:
        C.pline("%s flickers%s.", C.Yname2(obj), tailer);
        break;
    case C.OBJ_FLOOR:
        C.You_see("%s flicker%s.", C.an(C.xname(obj)), tailer);
        break;
    }
}

/* Print a dimming message for brass lanterns.  Only called if seen. */
function lantern_message(obj)
{
    /* from adventure */
    switch (obj.where) {
    case C.OBJ_INVENT:
        C.Your("lantern is getting dim.");
        if (C.Hallucination)
            C.pline("Batteries have not been invented yet.");
        break;
    case C.OBJ_FLOOR:
        C.You_see("a lantern getting dim.");
        break;
    case C.OBJ_MINVENT:
        C.pline("%s lantern is getting dim.", C.s_suffix(C.Monnam(obj.ocarry)));
        break;
    }
}

/*
 * Timeout callback for objects that are burning. E.g. lamps, candles.
 * See begin_burn() for meanings of obj->age and obj->spe.
 */
function burn_object(arg, timeout)
{
    timeout=C.long(timeout);
    let obj = arg.a_obj;
    let canseeit, many, menorah, need_newsym, need_invupdate, bytouch;
    const x = C.coordxyLocal(), y = C.coordxyLocal();
    const whose = C.stackAlloc(C.BUFSZ);

    menorah = obj.otyp == C.CANDELABRUM_OF_INVOCATION;
    many = menorah ? obj.spe > 1 : obj.quan > 1n;

    /* timeout while away */
    if (timeout != C.svm.moves) {
        let how_long = C.long(C.svm.moves - timeout);

        if (how_long >= obj.age) {
            obj.age = C.long(0);
            end_burn(obj, 0);

            if (menorah) {
                obj.spe = 0; /* no more candles */
                obj.owt = C.weight(obj);
            } else if (C.Is_candle(obj) || obj.otyp == C.POT_OIL) {
                let mtmp = 0;

                if (obj.where == C.OBJ_FLOOR)
                    mtmp = C.m_at(obj.ox, obj.oy);
                /* get rid of candles and burning oil potions;
                   we know this object isn't carried by hero,
                   nor is it migrating */
                C.obj_extract_self(obj);
                C.obfree(obj, 0);
                obj = 0;
                if (mtmp)
                    C.maybe_unhide_at(mtmp.mx, mtmp.my);
            }

        } else {
            obj.age -= how_long;
            begin_burn(obj, 1);
        }
        return;
    }

    /* only interested in INVENT, FLOOR, and MINVENT */
    if (C.get_obj_location(obj, x, y, 0)) {
        canseeit = Number(Boolean(!C.Blind && C.cansee(x.value, y.value)));
        /* set `whose[]' to be "Your " or "Fred's " or "The goblin's " */
        C.Shk_Your(whose, obj);
    } else {
        canseeit = 0;
    }
    /* when carrying the light source, you can feel the heat from lit lamp
       or candle so you'll be notified when it burns out even if blind at
       the time; brass lantern doesn't radiate sufficient heat for that
       (however, inventory formatting drops "(lit)" so player can tell) */
    bytouch = (Number(Boolean(obj.where == C.OBJ_INVENT && obj.otyp != C.BRASS_LANTERN)));
    need_newsym = need_invupdate = 0;

    /* obj->age is the age remaining at this point.  */
    switch (obj.otyp) {
    case C.POT_OIL:
        /* this should only be called when we run out */
        if (canseeit) {
            switch (obj.where) {
            case C.OBJ_INVENT:
                need_invupdate = 1;
                
                /*FALLTHRU*/
            case C.OBJ_MINVENT:
                C.pline("%spotion of oil has burnt away.", whose);
                break;
            case C.OBJ_FLOOR:
                C.You_see("a burning potion of oil go out.");
                need_newsym = 1;
                break;
            }
        }
        end_burn(obj, 0); /* turn off light source */
        if (C.carried(obj)) {
            C.useupall(obj);
        } else {
            /* clear migrating obj's destination code before obfree
               to avoid false complaint of deleting worn item */
            if (obj.where == C.OBJ_MIGRATING)
                obj.owornmask = 0n;
            C.obj_extract_self(obj);
            C.obfree(obj, 0);
        }
        obj = 0;
        break;

    case C.BRASS_LANTERN:
    case C.OIL_LAMP:
        switch (C.int(obj.age)) {
        case 150:
        case 100:
        case 50:
            if (canseeit) {
                if (obj.otyp == C.BRASS_LANTERN)
                    lantern_message(obj);
                else
                    see_lamp_flicker(obj,
                                     obj.age == 50n ? " considerably" : "");
            }
            break;

        case 25:
            if (canseeit) {
                if (obj.otyp == C.BRASS_LANTERN) {
                    lantern_message(obj);
                } else {
                    switch (obj.where) {
                    case C.OBJ_INVENT:
                    case C.OBJ_MINVENT:
                        C.pline("%s seems about to go out.", C.Yname2(obj));
                        break;
                    case C.OBJ_FLOOR:
                        C.You_see("%s about to go out.", C.an(C.xname(obj)));
                        break;
                    }
                }
            }
            break;

        case 0:
            /* even if blind you'll know if holding it */
            if (canseeit || bytouch) {
                switch (obj.where) {
                case C.OBJ_INVENT:
                    need_invupdate = 1;
                    
                    /*FALLTHRU*/
                case C.OBJ_MINVENT:
                    if (obj.otyp == C.BRASS_LANTERN)
                        C.pline("%slantern has run out of power.", whose);
                    else
                        C.pline("%s has gone out.", C.Yname2(obj));
                    break;
                case C.OBJ_FLOOR:
                    if (obj.otyp == C.BRASS_LANTERN)
                        C.You_see("a lantern run out of power.");
                    else
                        C.You_see("%s go out.", C.an(C.xname(obj)));
                    break;
                }
            }
            end_burn(obj, 0);
            break;

        default:
            /*
             * Someone added fuel to the lamp while it was
             * lit. Just fall through and let begin_burn()
             * handle the new age.
             */
            break;
        }

        if (obj.age)
            begin_burn(obj, 1);

        break;

    case C.CANDELABRUM_OF_INVOCATION:
    case C.TALLOW_CANDLE:
    case C.WAX_CANDLE:
        switch (obj.age) {
        case 75n:
            if (canseeit)
                switch (obj.where) {
                case C.OBJ_INVENT:
                case C.OBJ_MINVENT:
                    C.pline("%s%scandle%s getting short.", whose,
                          menorah ? "candelabrum's " : "",
                          many ? "s are" : " is");
                    break;
                case C.OBJ_FLOOR:
                    C.You_see("%scandle%s getting short.",
                            menorah ? "a candelabrum's " : many ? "some "
                                                                : "a ",
                            many ? "s" : "");
                    break;
                }
            break;

        case 15n:
            if (canseeit)
                switch (obj.where) {
                case C.OBJ_INVENT:
                case C.OBJ_MINVENT:
                    C.pline("%s%scandle%s flame%s flicker%s low!", whose,
                          menorah ? "candelabrum's " : "", many ? "s'" : "'s",
                          many ? "s" : "", many ? "" : "s");
                    break;
                case C.OBJ_FLOOR:
                    C.You_see("%scandle%s flame%s flicker low!",
                            menorah ? "a candelabrum's " : many ? "some "
                                                                : "a ",
                            many ? "s'" : "'s", many ? "s" : "");
                    break;
                }
            break;

        case 0n:
            /* we know even if blind and in our inventory */
            if (canseeit || bytouch) {
                if (menorah) {
                    switch (obj.where) {
                    case C.OBJ_INVENT:
                        need_invupdate = 1;
                        
                        /*FALLTHRU*/
                    case C.OBJ_MINVENT:
                        C.pline("%scandelabrum's flame%s.", whose,
                              many ? "s die" : " dies");
                        break;
                    case C.OBJ_FLOOR:
                        C.You_see("a candelabrum's flame%s die.",
                                many ? "s" : "");
                        break;
                    }
                } else {
                    switch (obj.where) {
                    case C.OBJ_INVENT:
                        /* no need_invupdate for update_inventory() necessary;
                           useupall() -> freeinv() handles it */
                           
                        /*FALLTHRU*/
                    case C.OBJ_MINVENT:
                        C.pline("%s %s consumed!", C.Yname2(obj),
                              many ? "are" : "is");
                        break;
                    case C.OBJ_FLOOR:
                        /*
                          You see some wax candles consumed!
                          You see a wax candle consumed!
                         */
                        C.You_see("%s%s consumed!", many ? "some " : "",
                                many ? C.xname(obj) : C.an(C.xname(obj)));
                        need_newsym = 1;
                        break;
                    }

                    /* post message */
                    C.pline(C.Hallucination
                              ? (many ? "They shriek!" : "It shrieks!")
                              : C.Blind ? "" : (many ? "Their flames die."
                                                   : "Its flame dies."));
                }
            }
            end_burn(obj, 0);

            if (menorah) {
                obj.spe = 0; /* no candles */
                obj.owt = C.weight(obj);
                if (C.carried(obj))
                    need_invupdate = 1;
            } else {
                if (C.carried(obj)) {
                    C.useupall(obj);
                } else {
                    let onfloor = (obj.where == C.OBJ_FLOOR);

                    /* clear migrating obj's destination code
                       so obfree won't think this item is worn */
                    if (obj.where == C.OBJ_MIGRATING)
                        obj.owornmask = 0n;
                    C.obj_extract_self(obj);
                    if (onfloor)
                        C.maybe_unhide_at(x.value, y.value);
                    C.obfree(obj, 0);
                }
                obj = 0;
            }
            break; /* case [age ==] 0 */

        default:
            /*
             * Someone added fuel (candles) to the menorah while
             * it was lit. Just fall through and let begin_burn()
             * handle the new age.
             */
            break;
        }

        if (obj && obj.age)
            begin_burn(obj, 1);
        break; /* case [otyp ==] candelabrum|tallow_candle|wax_candle */

    default:
        C.impossible("burn_object: unexpected obj %s", C.xname(obj));
        break;
    }
    if (need_newsym)
        C.newsym(x.value, y.value);
    if (need_invupdate)
        C.update_inventory();
}

/*
 * Start a burn timeout on the given object. If not "already lit" then
 * create a light source for the vision system.  There had better not
 * be a burn already running on the object.
 *
 * Magic lamps stay lit as long as there's a genie inside, so don't start
 * a timer.
 *
 * Burn rules:
 *      potions of oil, lamps & candles:
 *              age = # of turns of fuel left
 *              spe = <unused>
 *      magic lamps:
 *              age = <unused>
 *              spe = 0 not lightable, 1 lightable forever
 *      candelabrum:
 *              age = # of turns of fuel left
 *              spe = # of candles
 *
 * Once the burn begins, the age will be set to the amount of fuel
 * remaining _once_the_burn_finishes_.  If the burn is terminated
 * early then fuel is added back.
 *
 * This use of age differs from the use of age for corpses and eggs.
 * For the latter items, age is when the object was created, so we
 * know when it becomes "bad".
 *
 * This is a "silent" routine - it should not print anything out.
 */
function begin_burn(obj, already_lit)
{
    already_lit=C.boolean(already_lit);
    let radius = 3;
    let turns = C.long(0);
    let do_timer = 1;

    if (obj.age == 0 && obj.otyp != C.MAGIC_LAMP && !C.artifact_light(obj))
        return;

    switch (obj.otyp) {
    case C.MAGIC_LAMP:
        obj.lamplit = 1;
        do_timer = 0;
        break;

    case C.POT_OIL:
        turns = C.long(obj.age);
        if (obj.odiluted)
            turns = C.long((3n * turns + 2n) / 4n);
        radius = 1; /* very dim light */
        break;

    case C.BRASS_LANTERN:
    case C.OIL_LAMP:
        /* magic times are 150, 100, 50, 25, and 0 */
        if (obj.age > 150n)
            turns = C.long(obj.age - 150n);
        else if (obj.age > 100n)
            turns = C.long(obj.age - 100n);
        else if (obj.age > 50n)
            turns = C.long(obj.age - 50n);
        else if (obj.age > 25n)
            turns = C.long(obj.age - 25n);
        else
            turns = C.long(obj.age);
        break;

    case C.CANDELABRUM_OF_INVOCATION:
    case C.TALLOW_CANDLE:
    case C.WAX_CANDLE:
        /* magic times are 75, 15, and 0 */
        if (obj.age > 75n)
            turns = C.long(obj.age - 75n);
        else if (obj.age > 15n)
            turns = C.long(obj.age - 15n);
        else
            turns = C.long(obj.age);
        radius = C.candle_light_range(obj);
        break;

    default:
        /* [ALI] Support artifact light sources */
        if (C.artifact_light(obj)) {
            obj.lamplit = 1;
            do_timer = 0;
            radius = C.arti_light_radius(obj);
        } else {
            C.impossible("begin burn: unexpected %s", C.xname(obj));
            turns = C.long(obj.age);
        }
        break;
    }

    if (do_timer) {
        if (start_timer(turns, C.TIMER_OBJECT, C.BURN_OBJECT, C.obj_to_any(obj))) {
            obj.lamplit = 1;
            obj.age -= turns;
            if (C.carried(obj) && !already_lit)
                C.update_inventory();
        } else {
            obj.lamplit = 0;
        }
    } else {
        if (C.carried(obj) && !already_lit)
            C.update_inventory();
    }

    if (obj.lamplit && !already_lit) {
        const x = C.coordxyLocal(), y = C.coordxyLocal();

        if (C.get_obj_location(obj, x, y, C.CONTAINED_TOO | C.BURIED_TOO))
            C.new_light_source(x.value, y.value, radius, C.LS_OBJECT, C.obj_to_any(obj));
        else
            C.impossible("begin_burn: can't get obj position");
    }
}

/*
 * Stop a burn timeout on the given object if timer attached.  Darken
 * light source.
 */
function end_burn(obj, timer_attached)
{
    timer_attached=C.boolean(timer_attached);
    if (!obj.lamplit) {
        C.impossible("end_burn: obj %s not lit", C.xname(obj));
        return;
    }

    if (obj.otyp == C.MAGIC_LAMP || C.artifact_light(obj))
        timer_attached = 0;

    if (!timer_attached) {
        /* [DS] Cleanup explicitly, since timer cleanup won't happen */
        C.del_light_source(C.LS_OBJECT, C.obj_to_any(obj));
        obj.lamplit = 0;
        if (obj.where == C.OBJ_INVENT)
            C.update_inventory();
    } else if (!stop_timer(C.BURN_OBJECT, C.obj_to_any(obj)))
        C.impossible("end_burn: obj %s not timed!", C.xname(obj));
}

/*
 * Cleanup a burning object if timer stopped.
 */
function cleanup_burn(arg, expire_time)
{
    expire_time=C.long(expire_time);
    let obj = arg.a_obj;

    if (!obj.lamplit) {
        C.impossible("cleanup_burn: obj %s not lit", C.xname(obj));
        return;
    }

    C.del_light_source(C.LS_OBJECT, C.obj_to_any(obj));
    /* restore unused time */
    obj.age += expire_time - C.svm.moves;
    obj.lamplit = 0;

    if (obj.where == C.OBJ_INVENT)
        C.update_inventory();
}

function do_storms()
{
    let nstrike;
    let x, y;
    let dirx, diry;
    let count;

    /* no lightning if not stormy level or too often, even then */
    if (!C.svl.level.flags.stormy || (C.rngCaller(1855, "do_storms"), C.rn2(8, 1855, "do_storms", 1)))
        return;

    /* the number of strikes is 8-log2(nstrike) */
    for (nstrike = (C.rngCaller(1859, "do_storms"), C.rnd(64, 1859, "do_storms", 1)); nstrike <= 64; nstrike *= 2) {
        count = 0;
        do {
            x = (C.rngCaller(1862, "do_storms"), C.rnd(C.COLNO - 1, 1862, "do_storms", 1));
            y = (C.rngCaller(1863, "do_storms"), C.rn2(C.ROWNO, 1863, "do_storms", 1));
        } while (++count < 100 && C.levl[x][y].typ != C.CLOUD);

        if (count < 100) {
            dirx = (C.rngCaller(1867, "do_storms"), C.rn2(3, 1867, "do_storms", 1)) - 1;
            diry = (C.rngCaller(1868, "do_storms"), C.rn2(3, 1868, "do_storms", 1)) - 1;
            if (dirx != 0 || diry != 0) {
                /* BZ_M_SPELL(BZ_OFS_AD(AD_ELEC)): monster LIGHTNING spell */
                C.gb.buzzer = 0; /* unspecified attacker */
                C.buzz(C.BZ_M_SPELL(C.BZ_OFS_AD(C.AD_ELEC)), 8, x, y, dirx, diry);
            }
        }
    }

    if (C.levl[C.u.ux][C.u.uy].typ == C.CLOUD) {
        /* Inside a cloud during a thunderstorm is deafening. */
        /* Even if already deaf, we sense the thunder's vibrations. */
// Inactive sound macro:         C.Soundeffect(se_kaboom_boom_boom, 80);
        C.pline("Kaboom!!!  Boom!!  Boom!!");
        C.incr_itimeout(C.propertyRef("HDeaf"), (C.rngCaller(1882, "do_storms"), C.rn1(20, 30, 1882, "do_storms", 1)));
        C.disp.botl = 1;
        if (!C.u.uinvulnerable) {
            C.stop_occupation();
            C.nomul(-3);
            C.gm.multi_reason = "hiding from thunderstorm";
            C.gn.nomovemsg = 0;
        }
    } else
        C.You_hear("a rumbling noise.");
}

/* -------------------------------------------------------------------------
 */
/*
 * Generic Timeout Functions.
 *
 * Interface:
 *
 * General:
 *  boolean start_timer(long timeout,short kind,short func_index,
 *                      anything *arg)
 *      Start a timer of kind 'kind' that will expire at time
 *      svm.moves+'timeout'.  Call the function at 'func_index'
 *      in the timeout table using argument 'arg'.  Return TRUE if
 *      a timer was started.  This places the timer on a list ordered
 *      "sooner" to "later".  If an object, increment the object's
 *      timer count.
 *
 *  long stop_timer(short func_index, anything *arg)
 *      Stop a timer specified by the (func_index, arg) pair.  This
 *      assumes that such a pair is unique.  Return the time the
 *      timer would have gone off.  If no timer is found, return 0.
 *      If an object, decrement the object's timer count.
 *
 *  long peek_timer(short func_index, anything *arg)
 *      Return time specified timer will go off (0 if no such timer).
 *
 *  void run_timers(void)
 *      Call timers that have timed out.
 *
 * Save/Restore:
 *  void save_timers(NHFILE *, int range)
 *      Save all timers of range 'range'.  Range is either global
 *      or local.  Global timers follow game play, local timers
 *      are saved with a level.  Object and monster timers are
 *      saved using their respective ids instead of pointers.
 *
 *  void restore_timers(NHFILE *, int range, long adjust)
 *      Restore timers of range 'range'.  If from a ghost pile,
 *      adjust the timeout by 'adjust'.  The object and monster
 *      ids are not restored until later.
 *
 *  void relink_timers(boolean ghostly)
 *      Relink all object and monster timers that had been saved
 *      using their object's or monster's id number.
 *
 * Object Specific:
 *  void obj_move_timers(struct obj *src, struct obj *dest)
 *      Reassign all timers from src to dest.
 *
 *  void obj_split_timers(struct obj *src, struct obj *dest)
 *      Duplicate all timers assigned to src and attach them to dest.
 *
 *  void obj_stop_timers(struct obj *obj)
 *      Stop all timers attached to obj.
 *
 *  boolean obj_has_timer(struct obj *object, short timer_type)
 *      Check whether object has a timer of type timer_type.
 */


/* If defined, then include names when printing out the timer queue */
// #define VERBOSE_TIMER

// Original ttable declaration is represented by the JS callback catalogue.
/* ignore c for !VERBOSE_TIMER */

/*
 * Table of timeout functions, listed in order of enum timeout_types:
 */
const timeout_funcs = [
    /* object timers */
    {f: "rot_organic", cleanup: 0, name: "rot_organic"},
    {f: "rot_corpse", cleanup: 0, name: "rot_corpse"},
    {f: "revive_mon", cleanup: 0, name: "revive_mon"},
    {f: "zombify_mon", cleanup: 0, name: "zombify_mon"},
    {f: "burn_object", cleanup: "cleanup_burn", name: "burn_object"},
    {f: "hatch_egg", cleanup: 0, name: "hatch_egg"},
    {f: "fig_transform", cleanup: 0, name: "fig_transform"},
    {f: "shrink_glob", cleanup: 0, name: "shrink_glob"},
    /* level timers */
    {f: "melt_ice_away", cleanup: 0, name: "melt_ice_away"},
    /* currently no monster or global timers */
];
// #undef TTAB

function kind_name(kind)
{
    kind=C.short(kind);
    switch (kind) {
    case C.TIMER_NONE:
        C.impossible("no timer type");
        return "none";
    case C.TIMER_LEVEL:
        return "level";
    case C.TIMER_GLOBAL:
        return "global";
    case C.TIMER_OBJECT:
        return "object";
    case C.TIMER_MONSTER:
        return "monster";
    }
    return "unknown";
}

function print_queue(win, base)
{
    let curr;
    const buf = C.stackAlloc(C.BUFSZ);

    if (!base) {
        C.putstr(win, 0, " <empty>");
    } else {
        C.putstr(win, 0, "timeout  id   kind   call");
        for (curr = base; curr; curr = curr.next) {
            C.Sprintf(buf, " %4ld   %4ld  %-6s %s(%s)", curr.timeout,
                    C.long(curr.tid), kind_name(curr.kind),
                    C.timeout_funcs[curr.func_index].name,
                    C.fmt_ptr(curr.arg.a_void));
// #else
//             Sprintf(buf, " %4ld   %4ld  %-6s #%d(%s)", curr->timeout,
//                     curr->tid, kind_name(curr->kind), curr->func_index,
//                     fmt_ptr((genericptr_t) curr->arg.a_void));
// #endif
            C.putstr(win, 0, buf);
        }
    }
}

/* the #timeout command */
function wiz_timeout_queue()
{
    let win;
    const buf = C.stackAlloc(C.BUFSZ);
    let propname;
    let intrinsic;
    let i, p, count, longestlen, ln, specindx = 0;

    win = C.create_nhwindow(C.NHW_MENU); /* corner text window */
    if (win == C.WIN_ERR)
        return C.ECMD_OK;

    C.Sprintf(buf, "Current time = %ld.", C.svm.moves);
    C.putstr(win, 0, buf);
    C.putstr(win, 0, "");
    C.putstr(win, 0, "Active timeout queue:");
    C.putstr(win, 0, "");
    print_queue(win, C.gt.timer_base);

    /* Timed properties:
     * check every one; the majority can't obtain temporary timeouts in
     * normal play but those can be forced via the #wizintrinsic command.
     */
    count = longestlen = 0;
    for (i = 0; (propname = C.propertynames[i].prop_name) != 0; ++i) {
        p = C.propertynames[i].prop_num;
        intrinsic = C.long(C.u.uprops[p].intrinsic);
        if (intrinsic & C.TIMEOUT) {
            ++count;
            if ((ln = C.int(C.strlen(propname))) > longestlen)
                longestlen = ln;
        }
        if (specindx == 0 && p == C.COLD_RES) /* was FIRE_RES but has changed */
            specindx = i;
    }
    C.putstr(win, 0, "");
    if (!count) {
        C.putstr(win, 0, "No timed properties.");
    } else {
        C.putstr(win, 0, "Timed properties:");
        C.putstr(win, 0, "");
        for (i = 0; (propname = C.propertynames[i].prop_name) != 0; ++i) {
            p = C.propertynames[i].prop_num;
            intrinsic = C.long(C.u.uprops[p].intrinsic);
            if (intrinsic & C.TIMEOUT) {
                if (specindx > 0 && i >= specindx) {
                    C.putstr(win, 0, " -- settable via #wizintrinsic only --");
                    specindx = 0;
                }
                /* timeout value can be up to 16777215 (0x00ffffff) but
                   width of 4 digits should result in values lining up
                   almost all the time (if/when they don't, it won't
                   look nice but the information will still be accurate) */
                C.Sprintf(buf, " %*s %4ld", -longestlen, propname,
                        (intrinsic & C.TIMEOUT));
                C.putstr(win, 0, buf);
            }
        }
    }
    if (C.u.uswldtim) {
        C.putstr(win, 0, "");
        /* decremented when engulfer makes a move, so can last longer than
           the number of turns reported if engulfer is slow */
        C.Sprintf(buf, "Swallow countdown is %u.", C.u.uswldtim);
        C.putstr(win, 0, buf);
    }
    if (C.u.uinvault) {
        C.putstr(win, 0, "");
        C.Sprintf(buf, "Vault counter is %d.", C.u.uinvault);
        C.putstr(win, 0, buf);
    }
    if (C.any_visible_region()) {
        C.visible_region_summary(win);
    }
    if (C.svl.level.flags.stasis_until >= C.svm.moves) {
        C.putstr(win, 0, "");
        C.Sprintf(buf, "Level is no-teleport for %ld %s.",
                C.svl.level.flags.stasis_until - C.svm.moves + 1n,
                (C.svl.level.flags.stasis_until - C.svm.moves > 0n)
                  ? "turns" : "more turn");
        C.putstr(win, 0, buf);
    }
    C.display_nhwindow(win, 0);
    C.destroy_nhwindow(win);

    return C.ECMD_OK;
}

function timer_sanity_check()
{
    let curr;
    let t_id;
    const x = C.coordxyLocal(), y = C.coordxyLocal();

    for (curr = C.gt.timer_base; curr; curr = curr.next) {
        t_id = C.ulong(curr.tid);
        switch (curr.kind) {
        case C.TIMER_OBJECT: {
            /* TODO? verify that the timer type is attached to applicable
               object (egg for hatch, glob for shrink, and so forth) */
            let obj = curr.arg.a_obj, top;
            let obj_adr = C.fmt_ptr(obj);
            let owhere = obj.where;

            if (obj.timed == 0) {
                C.impossible("timer sanity: untimed obj %s, timer %lu",
                           obj_adr, t_id);
            }
            x.value = y.value = 0;
            /* if obj is in a container, possibly a nested one, figure out
               where the outermost container is */
            for (top = obj; top; top = top.ocontainer)
                if ((owhere = top.where) != C.OBJ_CONTAINED)
                    break;
            C.assert(top != 0, 0);
            if (owhere == C.OBJ_MIGRATING
                || (owhere == C.OBJ_MINVENT && !mon_is_local(top.ocarry))) {
                /* migrating directly or carried by migrating monster */
                ; /* not able to validate location so skip checks */
            } else if (!C.get_obj_location(obj, x, y,
                                         C.CONTAINED_TOO | C.BURIED_TOO)) {
                /* free? or on a shop's used-up bill? */
                C.impossible(
                    "timer sanity: can't locate obj %s [where=%d], timer %lu",
                           obj_adr, obj.where, t_id);
            } else if (!C.isok(x.value, y.value)) {
                C.impossible(
              "timer sanity: obj %s [where=%d] located at <%d,%d>, timer %lu",
                           obj_adr, obj.where, x.value, y.value, t_id);
            }
            break;
        }
        case C.TIMER_MONSTER:
            C.impossible("timer sanity: unexpected monster timer %lu", t_id);
            break;
        case C.TIMER_LEVEL: {
            let lwhere = C.long(curr.arg.a_long);

            x.value = C.coordxy(((lwhere >> C.long(16)) & C.long(0xFFFF)));
            y.value = C.coordxy((lwhere & C.long(0xFFFF)));
            if (C.isok(x.value, y.value)) {
                /* replicate isok() in order to convince static analysis
                   that the decoding via '& 0xFFFF' hasn't produced a value
                   too big for levl[][] and that the cast to a narrower type
                   hasn't intruded on the sign bit to yield a negative value;
                   the analyzer isn't aware that isok() filters such things */
                C.assert(Number(Boolean(x.value > 0 && x.value < C.COLNO && y.value >= 0 && y.value < C.ROWNO)), 1);

                if (curr.func_index == C.MELT_ICE_AWAY && !C.is_ice(x.value, y.value)
                    /* the terrain under the span of an open drawbridge might
                       be frozen moat; is_ice() only checks for that when
                       the drawbridge is closed (and terrain here would be
                       DRAWBRIGE_UP) */
                    && !(C.levl[x.value][y.value].typ == C.DRAWBRIDGE_DOWN
                         && (C.levl[x.value][y.value].drawbridgemask & C.DB_UNDER) == C.DB_ICE))
                    C.impossible(
                         "timer sanity: melt timer %lu on non-ice %d <%d,%d>",
                               t_id, C.levl[x.value][y.value].typ, x.value, y.value);
            } else {
                C.impossible("timer sanity: spot timer %lu at <%d,%d>",
                           t_id, x.value, y.value);
            }
            break;
        }
        case C.TIMER_GLOBAL:
            C.impossible("timer sanity: unexpected global timer %lu", t_id);
            break;
        default:
            C.impossible("timer sanity: unknown timer %lu, type: %d",
                       t_id, curr.kind);
            break;
        }
    }
}

/*
 * Pick off timeout elements from the global queue and call their functions.
 * Do this until their time is less than or equal to the move count.
 */
function run_timers()
{
    let curr;

    /*
     * Always use the first element.  Elements may be added or deleted at
     * any time.  The list is ordered; we are done when the first element
     * is in the future.
     */
    while (C.gt.timer_base && C.gt.timer_base.timeout <= C.svm.moves) {
        curr = C.gt.timer_base;
        C.gt.timer_base = curr.next;

        if (curr.kind == C.TIMER_OBJECT)
            (curr.arg.a_obj).timed--;
        C.callTimeout(C.timeout_funcs[curr.func_index].f, curr.arg, curr.timeout);
        C.memset(curr, 0, C.timerSize);
        C.free(curr.address);
    }
}

/*
 * Start a timer.  Return TRUE if successful.
 */
function start_timer(when, kind, func_index, arg)
{
    when=C.long(when);kind=C.short(kind);func_index=C.short(func_index);
    let gnu, dup;

    if (kind <= C.TIMER_NONE || kind >= C.NUM_TIMER_KINDS
        || func_index < 0 || func_index >= C.NUM_TIME_FUNCS)
        C.panic("start_timer (%s: %d)", kind_name(kind), C.int(func_index));

    /* fail if <arg> already has a <func_index> timer running */
    for (dup = C.gt.timer_base; dup; dup = dup.next)
        if (dup.kind == kind
            && dup.func_index == func_index
            && C.samePtr(dup.arg.a_void, arg.a_void))
            break;
    if (dup) {
        const idbuf = C.stackAlloc(C.QBUFSZ);

        C.Sprintf(idbuf, "%s timer", C.timeout_funcs[func_index].name);
// #else
//         Sprintf(idbuf, "%s timer (%d)", kind_name(kind), (int) func_index);
// #endif
        C.impossible("Attempted to start duplicate %s, aborted.", idbuf);
        return 0;
    }

    gnu = C.timer(C.alloc(C.timerSize));
    C.memset(gnu.address, 0, C.timerSize);
    gnu.next = 0;
    gnu.tid = C.long(C.svt.timer_id++);
    gnu.timeout = C.svm.moves + when;
    gnu.kind = kind;
    gnu.needs_fixup = 0;
    gnu.func_index = func_index;
    C.copyAnything(gnu.arg, arg);
    insert_timer(gnu);

    if (kind == C.TIMER_OBJECT) /* increment object's timed count */
        (arg.a_obj).timed++;

    return 1;
}

/*
 * Remove the timer from the current list and free it up.  Return the time
 * remaining until it would have gone off, 0 if not found.
 */
function stop_timer(func_index, arg)
{
    func_index=C.short(func_index);
    let cleanup_func;
    let doomed;
    let timeout;

    doomed = remove_timer(C.timerBaseRef(), func_index, arg);

    if (doomed) {
        timeout = C.long(doomed.timeout);
        if (doomed.kind == C.TIMER_OBJECT)
            (arg.a_obj).timed--;
        if ((cleanup_func = C.timeout_funcs[doomed.func_index].cleanup) != 0)
            C.callTimeout(cleanup_func, arg, timeout);
        C.memset(doomed, 0, C.timerSize);
        C.free(doomed.address);
        return (C.long(timeout - C.svm.moves));
    }
    return C.long(0n);
}

/*
 * Find the timeout of specified timer; return 0 if none.
 */
function peek_timer(type, arg)
{
    type=C.short(type);
    let curr;

    for (curr = C.gt.timer_base; curr; curr = curr.next) {
        if (curr.func_index == type && C.samePtr(curr.arg.a_void, arg.a_void))
            return C.long(curr.timeout);
    }
    return C.long(0n);
}

/*
 * Move all object timers from src to dest, leaving src untimed.
 */
function obj_move_timers(src, dest)
{
    let count;
    let curr;

    for (count = 0, curr = C.gt.timer_base; curr; curr = curr.next)
        if (curr.kind == C.TIMER_OBJECT && C.samePtr(curr.arg.a_obj, src)) {
            curr.arg.a_obj = dest;
            dest.timed++;
            count++;
        }
    if (count != src.timed)
        C.panic("obj_move_timers");
    src.timed = 0;
}

/*
 * Find all object timers and duplicate them for the new object "dest".
 */
function obj_split_timers(src, dest)
{
    let curr, next_timer = 0;

    for (curr = C.gt.timer_base; curr; curr = next_timer) {
        next_timer = curr.next; /* things may be inserted */
        if (curr.kind == C.TIMER_OBJECT && C.samePtr(curr.arg.a_obj, src)) {
            start_timer(curr.timeout - C.svm.moves, C.TIMER_OBJECT,
                               curr.func_index, C.obj_to_any(dest));
        }
    }
}

/*
 * Stop all timers attached to this object.  We can get away with this because
 * all object pointers are unique.
 */
function obj_stop_timers(obj)
{
    let cleanup_func;
    let curr, prev, next_timer = 0;

    for (prev = 0, curr = C.gt.timer_base; curr; curr = next_timer) {
        next_timer = curr.next;
        if (curr.kind == C.TIMER_OBJECT && C.samePtr(curr.arg.a_obj, obj)) {
            if (prev)
                prev.next = curr.next;
            else
                C.gt.timer_base = curr.next;
            if ((cleanup_func = C.timeout_funcs[curr.func_index].cleanup) != 0)
                C.callTimeout(cleanup_func, curr.arg, curr.timeout);
            C.memset(curr, 0, C.timerSize);
            C.free(curr.address);
        } else {
            prev = curr;
        }
    }
    obj.timed = 0;
}

/*
 * Check whether object has a timer of type timer_type.
 */
function obj_has_timer(object, timer_type)
{
    timer_type=C.short(timer_type);
    let timeout = C.long(peek_timer(timer_type, C.obj_to_any(object)));

    return C.boolean((timeout != 0n));
}

/*
 * Stop all timers of index func_index at this spot.
 *
 */
function spot_stop_timers(x, y, func_index)
{
    x=C.coordxy(x);y=C.coordxy(y);func_index=C.short(func_index);
    let cleanup_func;
    let curr, prev, next_timer = 0;
    let where = (C.long((C.long(x) << C.long(16)) | (C.long(y))));

    for (prev = 0, curr = C.gt.timer_base; curr; curr = next_timer) {
        next_timer = curr.next;
        if (curr.kind == C.TIMER_LEVEL && curr.func_index == func_index
            && curr.arg.a_long == where) {
            if (prev)
                prev.next = curr.next;
            else
                C.gt.timer_base = curr.next;
            if ((cleanup_func = C.timeout_funcs[curr.func_index].cleanup) != 0)
                C.callTimeout(cleanup_func, curr.arg, curr.timeout);
            C.memset(curr, 0, C.timerSize);
            C.free(curr.address);
        } else {
            prev = curr;
        }
    }
}

/*
 * When is the spot timer of type func_index going to expire?
 * Returns 0L if no such timer.
 */
function spot_time_expires(x, y, func_index)
{
    x=C.coordxy(x);y=C.coordxy(y);func_index=C.short(func_index);
    let curr;
    let where = (C.long((C.long(x) << C.long(16)) | (C.long(y))));

    for (curr = C.gt.timer_base; curr; curr = curr.next) {
        if (curr.kind == C.TIMER_LEVEL && curr.func_index == func_index
            && curr.arg.a_long == where)
            return C.long(curr.timeout);
    }
    return C.long(0n);
}

function spot_time_left(x, y, func_index)
{
    x=C.coordxy(x);y=C.coordxy(y);func_index=C.short(func_index);
    let expires = C.long(spot_time_expires(x, y, func_index));
    return C.long((expires > 0n) ? expires - C.svm.moves : 0n);
}

/* Insert timer into the global queue */
function insert_timer(gnu)
{
    let curr, prev;

    for (prev = 0, curr = C.gt.timer_base; curr; prev = curr, curr = curr.next)
        if (curr.timeout >= gnu.timeout)
            break;

    gnu.next = curr;
    if (prev)
        prev.next = gnu;
    else
        C.gt.timer_base = gnu;
}

function remove_timer(base, func_index, arg)
{
    func_index=C.short(func_index);
    let prev, curr;

    for (prev = 0, curr = base.value; curr; prev = curr, curr = curr.next)
        if (curr.func_index == func_index && C.samePtr(curr.arg.a_void, arg.a_void))
            break;

    if (curr) {
        if (prev)
            prev.next = curr.next;
        else
            base.value = curr.next;
    }

    return curr;
}

function write_timer(nhfp, timer)
{
    const arg_save = C.anyLocal();

    C.copyAnything(arg_save, C.cg.zeroany);
    switch (timer.kind) {
    case C.TIMER_GLOBAL:
    case C.TIMER_LEVEL:
        /* assume no pointers in arg */
        C.Sfo_fe(nhfp, timer, "timer");
        break;

    case C.TIMER_OBJECT:
        if (timer.needs_fixup) {
            C.Sfo_fe(nhfp, timer, "timer");
        } else {
            /* replace object pointer with id */
            arg_save.a_obj = timer.arg.a_obj;
            C.copyAnything(timer.arg, C.cg.zeroany);
            timer.arg.a_uint = (arg_save.a_obj).o_id;
            timer.needs_fixup = 1;
            C.Sfo_fe(nhfp, timer, "timer");
            timer.arg.a_obj = arg_save.a_obj;
            timer.needs_fixup = 0;
        }
        break;

    case C.TIMER_MONSTER:
        if (timer.needs_fixup) {
            C.Sfo_fe(nhfp, timer, "timer");
        } else {
            /* replace monster pointer with id */
            arg_save.a_monst = timer.arg.a_monst;
            C.copyAnything(timer.arg, C.cg.zeroany);
            timer.arg.a_uint = (arg_save.a_monst).m_id;
            timer.needs_fixup = 1;
            C.Sfo_fe(nhfp, timer, "timer");
            timer.arg.a_monst = arg_save.a_monst;
            timer.needs_fixup = 0;
        }
        break;

    default:
        C.panic("write_timer");
        break;
    }
}



/*
 * Return TRUE if the object will stay on the level when the level is
 * saved.
 */
function obj_is_local(obj)
{
    switch (obj.where) {
    case C.OBJ_INVENT:
    case C.OBJ_MIGRATING:
        return 0;
    case C.OBJ_FLOOR:
    case C.OBJ_BURIED:
        return 1;
    case C.OBJ_CONTAINED:
        return obj_is_local(obj.ocontainer);
    case C.OBJ_MINVENT:
        return mon_is_local(obj.ocarry);
    }
    C.panic("obj_is_local");
    /*NOTREACHED*/
    return 0;
}

/*
 * Return TRUE if the given monster will stay on the level when the
 * level is saved.
 */
function mon_is_local(mon)
{
    let curr;

    for (curr = C.gm.migrating_mons; curr; curr = curr.nmon)
        if (C.samePtr(curr, mon))
            return 0;
    /* `gm.mydogs' is used during level changes, never saved and restored */
    for (curr = C.gm.mydogs; curr; curr = curr.nmon)
        if (C.samePtr(curr, mon))
            return 0;
    return 1;
}

/*
 * Return TRUE if the timer is attached to something that will stay on the
 * level when the level is saved.
 */
function timer_is_local(timer)
{
    switch (timer.kind) {
    case C.TIMER_LEVEL:
        return 1;
    case C.TIMER_GLOBAL:
        return 0;
    case C.TIMER_OBJECT:
        return obj_is_local(timer.arg.a_obj);
    case C.TIMER_MONSTER:
        return mon_is_local(timer.arg.a_monst);
    }
    C.panic("timer_is_local");
    /*NOTREACHED*/
    return 0;
}



/*
 * Part of the save routine.  Count up the number of timers that would
 * be written.  If write_it is true, actually write the timer.
 */
function maybe_write_timer(nhfp, range, write_it)
{
    range=C.int(range);write_it=C.boolean(write_it);
    let count = 0;
    let curr;

    for (curr = C.gt.timer_base; curr; curr = curr.next) {
        if (range == C.RANGE_GLOBAL) {
            /* global timers */

            if (!timer_is_local(curr)) {
                count++;
                if (write_it) write_timer(nhfp, curr);
            }
        } else {
            /* local timers */

            if (timer_is_local(curr)) {
                count++;
                if (write_it) write_timer(nhfp, curr);
            }
        }
    }

    return count;
}


/*
 * Save part of the timer list.  The parameter 'range' specifies either
 * global or level timers to save.  The timer ID is saved with the global
 * timers.
 *
 * Global range:
 *      + timeouts that follow the hero (global)
 *      + timeouts that follow obj & monst that are migrating
 *
 * Level range:
 *      + timeouts that are level-specific (e.g. storms)
 *      + timeouts that stay with the level (obj & monst)
 */
function save_timers(nhfp, range)
{
    range=C.int(range);
    let curr, prev, next_timer = 0;
    const count = C.intLocal();

    if (C.update_file(nhfp)) {
        if (range == C.RANGE_GLOBAL) {
            C.Sfo_ulong(nhfp, C.timerIdRef(), "timer-timer_id");
        }
        count.value = maybe_write_timer(nhfp, range, 0);
        C.Sfo_int(nhfp, count, "timer-timer_count");
        maybe_write_timer(nhfp, range, 1);
    }

    if (C.release_data(nhfp)) {
        for (prev = 0, curr = C.gt.timer_base; curr; curr = next_timer) {
            next_timer = curr.next; /* in case curr is removed */

            if (!(!!(range == C.RANGE_LEVEL) ^ !!timer_is_local(curr))) {
                if (prev)
                    prev.next = curr.next;
                else
                    C.gt.timer_base = curr.next;
                C.memset(curr, 0, C.timerSize);
                C.free(curr.address);
                /* prev stays the same */
            } else {
                prev = curr;
            }
        }
    }
}
// #endif /* !SFCTOOL */

/*
 * Pull in the structures from disk, but don't recalculate the object and
 * monster pointers.
 */
function restore_timers(nhfp, range, adjust)
{
    range=C.int(range);adjust=C.long(adjust);
    const count = C.intLocal(0);
    let curr;
    let ghostly = (nhfp.ftype == C.NHF_BONESFILE); /* from a ghost level */

    if (range == C.RANGE_GLOBAL) {
        C.Sfi_ulong(nhfp, C.timerIdRef(), "timer-timer_id");
    }

    /* restore elements */
    C.Sfi_int(nhfp, count, "timer-timer_count");
    while (count.value-- > 0) {
        curr = C.timer(C.alloc(C.timerSize));
        C.Sfi_fe(nhfp, curr, "timer");
        if (ghostly)
            curr.timeout += adjust;
// #ifndef SFCTOOL
        insert_timer(curr);
// #endif
    }
}

// #ifndef SFCTOOL


/* to support '#stats' wizard-mode command */
function timer_stats(hdrfmt, hdrbuf, count, size)
{
    let te;

    C.Sprintf(hdrbuf, hdrfmt, C.long(C.timerSize));
    count.value = size.value = 0n;
    for (te = C.gt.timer_base; te; te = te.next) {
        ++count.value;
        size.value += C.long(C.timerSize);
    }
}



/* reset all timers that are marked for resetting */
function relink_timers(ghostly)
{
    ghostly=C.boolean(ghostly);
    let curr;
    const nid = C.uintLocal();

    for (curr = C.gt.timer_base; curr; curr = curr.next) {
        if (curr.needs_fixup) {
            if (curr.kind == C.TIMER_OBJECT) {
                if (ghostly) {
                    if (!C.lookup_id_mapping(curr.arg.a_uint, nid))
                        C.panic("relink_timers 1");
                } else
                    nid.value = curr.arg.a_uint;
                curr.arg.a_obj = C.find_oid(nid.value);
                if (!curr.arg.a_obj)
                    C.panic("can't find o_id %d", nid.value);
                curr.needs_fixup = 0;
            } else if (curr.kind == C.TIMER_MONSTER) {
                C.panic("relink_timers: no monster timer implemented");
            } else
                C.panic("relink_timers 2");
        }
    }
}
// #endif /* !SFCTOOL */

